"""Read and write the YAML settings files the app ships with."""
import warnings

import yaml

try:  # the libyaml-backed loader when PyYAML was built with it
    from yaml import CSafeLoader as FastSafeLoader
except ImportError:
    from yaml import SafeLoader as FastSafeLoader


def load_settings(text):
    return yaml.load(text)


def load_settings_quiet(text):
    """Same as load_settings, without the no-Loader warning PyYAML 5 prints."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", yaml.YAMLLoadWarning)
        return load_settings(text)


def load_documents(text):
    return list(yaml.load_all(text))


def load_trusted(text):
    return yaml.load(text, Loader=yaml.FullLoader)


def load_fast(text):
    return yaml.load(text, Loader=FastSafeLoader)


def dump_settings(data):
    return yaml.dump(data, default_flow_style=False)


def dump_ordered(data):
    return yaml.dump(data, sort_keys=False, allow_unicode=True)


def dump_safe(data):
    return yaml.safe_dump(data, indent=4)


def merge(base, override):
    merged = dict(base)
    merged.update(override or {})
    return merged

