import datetime

from app import settings

TEXT = """\
name: demo
retries: 3
ratio: 0.5
launch: 2024-01-02
tags: [a, b]
db: {host: localhost, port: 5432}
"""

EXPECTED = {
    "name": "demo",
    "retries": 3,
    "ratio": 0.5,
    "launch": datetime.date(2024, 1, 2),
    "tags": ["a", "b"],
    "db": {"host": "localhost", "port": 5432},
}


def test_load_variants_agree():
    assert settings.load_settings(TEXT) == EXPECTED
    assert settings.load_settings_quiet(TEXT) == EXPECTED
    assert settings.load_trusted(TEXT) == EXPECTED
    assert settings.load_fast(TEXT) == EXPECTED


def test_load_documents():
    docs = settings.load_documents("a: 1\n---\nb: 2\n")
    assert docs == [{"a": 1}, {"b": 2}]


def test_dump_default_style():
    out = settings.dump_settings({"b": 1, "a": {"x": [1, 2]}})
    assert out == "a:\n  x:\n  - 1\n  - 2\nb: 1\n"


def test_dump_ordered_keeps_insertion_order():
    out = settings.dump_ordered({"zeta": 1, "alpha": "caf\u00e9"})
    assert out == "zeta: 1\nalpha: caf\u00e9\n"


def test_dump_safe_and_roundtrip():
    out = settings.dump_safe({"k": {"a": 1}})
    assert out == "k:\n    a: 1\n"
    assert settings.load_fast(out) == {"k": {"a": 1}}


def test_merge():
    assert settings.merge({"a": 1}, {"b": 2}) == {"a": 1, "b": 2}
    assert settings.merge({"a": 1}, None) == {"a": 1}

